solution.solution.py:
def to_fahrenheit(celsius):
    return celsius * 9 / 5 + 32


def describe(celsius):
    if celsius <= 0:
        return "freezing"
    if celsius < 15:
        return "cold"
    if celsius < 25:
        return "mild"
    return "hot"


def forecast_line(day, celsius):
    return f"{day}: {celsius:.1f}°C / {to_fahrenheit(celsius):.1f}°F ({describe(celsius)})"

