@test("conversion")
def _():
    check_eq(to_fahrenheit(100), 212)
    check_eq(to_fahrenheit(-40), -40)
    check_near(to_fahrenheit(18), 64.4)

@test("descriptions at the edges")
def _():
    check_eq(describe(0), "freezing")
    check_eq(describe(0.1), "cold")
    check_eq(describe(15), "mild")
    check_eq(describe(24.9), "mild")
    check_eq(describe(25), "hot")

@test("forecast lines")
def _():
    check_eq(forecast_line("Mon", 18), "Mon: 18.0°C / 64.4°F (mild)")
    check_eq(forecast_line("Tue", -3.25), "Tue: -3.2°C / 26.1°F (freezing)")

